#include <iostream>

class Konto {
public:
    Konto(int start) : stand(start) {}

    void einzahlen(int betrag) {
        if (betrag <= 0) {
            std::cout << "Betrag muss positiv sein\n";
            return;
        }
        stand += betrag;
    }

    int getStand() const {
        return stand;
    }

private:
    int stand;
};

int main() {
    Konto k(100);
    k.einzahlen(50);
    k.einzahlen(-20);
    std::cout << "Stand: " << k.getStand() << "\n";
    return 0;
}

#include <iostream>
#include <string>

class Tier {
public:
    Tier(std::string name) : name(name) {}

    virtual std::string gib_laut() const {
        return "...";
    }

protected:
    std::string name;
};

class Katze : public Tier {
public:
    Katze(std::string name) : Tier(name) {}

    std::string gib_laut() const override {
        return "Miau";
    }
};

int main() {
    Katze k("Mimi");
    Tier& tier = k;               // Referenz auf die Basisklasse
    std::cout << k.gib_laut() << "\n";
    std::cout << tier.gib_laut() << "\n";
    return 0;
}

#include <iostream>

class Rechteck {
public:
    Rechteck(int breite, int hoehe) : breite(breite), hoehe(hoehe) {}

    int flaeche() const {
        return breite * hoehe;
    }

    int umfang() const {
        return 2 * (breite + hoehe);
    }

    bool ist_quadrat() const {
        return breite == hoehe;
    }

private:
    int breite;
    int hoehe;
};

int main() {
    Rechteck r(4, 5);
    std::cout << "Fläche: " << r.flaeche() << "\n";
    std::cout << "Umfang: " << r.umfang() << "\n";
    std::cout << "Quadrat: " << (r.ist_quadrat() ? "ja" : "nein") << "\n";
    return 0;
}

