#include <iostream>

class Zaehler {
public:
    Zaehler() { ++anzahl; }
    ~Zaehler() { --anzahl; }

    static int anzahl;   // gehört zur Klasse, nicht zum Objekt
};

int Zaehler::anzahl = 0;   // Definition außerhalb der Klasse

int main() {
    std::cout << Zaehler::anzahl << "\n";
    {
        Zaehler a;
        Zaehler b;
        std::cout << Zaehler::anzahl << "\n";
    }
    std::cout << Zaehler::anzahl << "\n";
    return 0;
}

#include <iostream>
#include <string>

class Fahrzeug {
public:
    Fahrzeug(std::string marke, int raeder) : marke(marke), raeder(raeder) {}

    std::string beschreibung() const {
        return marke + " mit " + std::to_string(raeder) + " Rädern";
    }

protected:
    std::string marke;
    int raeder;
};

class Auto : public Fahrzeug {
public:
    Auto(std::string marke, int tueren)
        : Fahrzeug(marke, 4), tueren(tueren) {}

    std::string beschreibung() const {
        return Fahrzeug::beschreibung() + ", " + std::to_string(tueren) + " Türen";
    }

private:
    int tueren;
};

int main() {
    Auto a("VW", 5);
    std::cout << a.beschreibung() << "\n";
    return 0;
}
